import json
from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

router = APIRouter(prefix="/agent/support/tools")

class ToolInvocation(BaseModel):
    function_name: str
    arguments_json: str

@router.post("/fetch-attachments")
async def fetch_ticket_attachments(
    invocation: ToolInvocation,
    current_user: User = Depends(get_authenticated_customer),
    ticket_store: TicketStore = Depends(get_ticket_store)
):
    if invocation.function_name != "get_ticket_attachments":
        raise HTTPException(status_code=400, detail="Invalid tool")

    try:
        params = json.loads(invocation.arguments_json)
    except json.JSONDecodeError:
        raise HTTPException(status_code=400, detail="Malformed arguments JSON")

    ticket_id = params.get("ticket_id")
    if not ticket_id:
        raise HTTPException(status_code=400, detail="Missing ticket_id")

    ticket = await ticket_store.get_ticket_by_id(ticket_id=ticket_id)
    if not ticket or ticket.customer_id != current_user.customer_id:
        raise HTTPException(status_code=404, detail="Ticket not found")

    attachments = await ticket_store.list_attachments_by_ticket(ticket_id=ticket_id)
    return {
        "ticket_id": ticket_id,
        "attachments": [
            {"filename": a.filename, "download_url": a.download_url, "uploaded_at": a.uploaded_at}
            for a in attachments
        ]
    }
